PRAGMA foreign_keys = ON;
CREATE TABLE users (id TEXT PRIMARY KEY, email TEXT NOT NULL COLLATE NOCASE UNIQUE, password_hash TEXT NOT NULL, password_algorithm TEXT NOT NULL, password_parameters TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'member' CHECK(role IN ('admin','member','patient','moderator')), status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('pending_verification','active','blocked','disabled')), display_name TEXT NOT NULL, avatar_key TEXT, email_verified_at TEXT, last_login_at TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, deleted_at TEXT);
CREATE TABLE sessions (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, csrf_secret_hash TEXT NOT NULL, ip_hash TEXT, user_agent TEXT, created_at TEXT NOT NULL, last_seen_at TEXT NOT NULL, expires_at TEXT NOT NULL, revoked_at TEXT);
CREATE INDEX sessions_user_expiry_idx ON sessions(user_id, expires_at);
CREATE TABLE password_resets (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, token_hash TEXT NOT NULL UNIQUE, created_at TEXT NOT NULL, expires_at TEXT NOT NULL, used_at TEXT, requested_ip_hash TEXT);
CREATE INDEX password_resets_user_idx ON password_resets(user_id, created_at);
CREATE TABLE email_verifications (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, token_hash TEXT NOT NULL UNIQUE, created_at TEXT NOT NULL, expires_at TEXT NOT NULL, used_at TEXT);
CREATE TABLE courses (id TEXT PRIMARY KEY, slug TEXT NOT NULL UNIQUE, title TEXT NOT NULL, description TEXT, cover_key TEXT, status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','published','archived')), created_by TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, deleted_at TEXT);
CREATE TABLE modules (id TEXT PRIMARY KEY, course_id TEXT NOT NULL REFERENCES courses(id) ON DELETE CASCADE, title TEXT NOT NULL, description TEXT, position INTEGER NOT NULL CHECK(position>=0), status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','published')), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, deleted_at TEXT, UNIQUE(course_id,position));
CREATE TABLE lessons (id TEXT PRIMARY KEY, module_id TEXT NOT NULL REFERENCES modules(id) ON DELETE CASCADE, title TEXT NOT NULL, slug TEXT NOT NULL, description TEXT, body_html TEXT, cover_key TEXT, video_provider TEXT, video_reference TEXT, position INTEGER NOT NULL CHECK(position>=0), status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','published')), published_at TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, deleted_at TEXT, UNIQUE(module_id,slug), UNIQUE(module_id,position));
CREATE TABLE lesson_materials (id TEXT PRIMARY KEY, lesson_id TEXT NOT NULL REFERENCES lessons(id) ON DELETE CASCADE, title TEXT NOT NULL, object_key TEXT NOT NULL UNIQUE, file_name TEXT NOT NULL, content_type TEXT NOT NULL, size_bytes INTEGER NOT NULL CHECK(size_bytes>=0), position INTEGER NOT NULL CHECK(position>=0), status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','hidden')), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(lesson_id,position));
CREATE TABLE enrollments (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), course_id TEXT NOT NULL REFERENCES courses(id), status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','paused','completed','cancelled','expired')), enrolled_at TEXT NOT NULL, starts_at TEXT, expires_at TEXT, completed_at TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(user_id,course_id));
CREATE INDEX enrollments_course_status_idx ON enrollments(course_id,status);
CREATE TABLE lesson_progress (id TEXT PRIMARY KEY, enrollment_id TEXT NOT NULL REFERENCES enrollments(id) ON DELETE CASCADE, lesson_id TEXT NOT NULL REFERENCES lessons(id) ON DELETE CASCADE, status TEXT NOT NULL DEFAULT 'not_started' CHECK(status IN ('not_started','in_progress','completed')), progress_percent INTEGER NOT NULL DEFAULT 0 CHECK(progress_percent BETWEEN 0 AND 100), last_position_seconds INTEGER NOT NULL DEFAULT 0 CHECK(last_position_seconds>=0), first_started_at TEXT, last_viewed_at TEXT, completed_at TEXT, updated_at TEXT NOT NULL, UNIQUE(enrollment_id,lesson_id));
CREATE TABLE conversations (id TEXT PRIMARY KEY, subject TEXT, kind TEXT NOT NULL DEFAULT 'direct' CHECK(kind IN ('direct','support')), status TEXT NOT NULL DEFAULT 'open' CHECK(status IN ('open','closed')), created_by TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE conversation_participants (conversation_id TEXT NOT NULL REFERENCES conversations(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, joined_at TEXT NOT NULL, PRIMARY KEY(conversation_id,user_id));
CREATE INDEX conversation_participants_user_idx ON conversation_participants(user_id,conversation_id);
CREATE TABLE messages (id TEXT PRIMARY KEY, conversation_id TEXT NOT NULL REFERENCES conversations(id) ON DELETE CASCADE, sender_id TEXT NOT NULL REFERENCES users(id), body TEXT NOT NULL, created_at TEXT NOT NULL, edited_at TEXT, deleted_at TEXT);
CREATE INDEX messages_conversation_created_idx ON messages(conversation_id,created_at);
CREATE TABLE message_attachments (id TEXT PRIMARY KEY, message_id TEXT NOT NULL REFERENCES messages(id) ON DELETE CASCADE, object_key TEXT NOT NULL UNIQUE, file_name TEXT NOT NULL, content_type TEXT NOT NULL, size_bytes INTEGER NOT NULL CHECK(size_bytes>=0), created_at TEXT NOT NULL);
CREATE TABLE message_reads (message_id TEXT NOT NULL REFERENCES messages(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, read_at TEXT NOT NULL, PRIMARY KEY(message_id,user_id));
CREATE INDEX message_reads_user_idx ON message_reads(user_id,read_at);
CREATE TABLE announcements (id TEXT PRIMARY KEY, title TEXT NOT NULL, body TEXT NOT NULL, audience_role TEXT CHECK(audience_role IS NULL OR audience_role IN ('admin','member','patient','moderator')), status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','published','archived')), published_at TEXT, expires_at TEXT, created_by TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE notifications (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, type TEXT NOT NULL, title TEXT NOT NULL, body TEXT, action_path TEXT, source_type TEXT, source_id TEXT, created_at TEXT NOT NULL, read_at TEXT);
CREATE INDEX notifications_user_unread_idx ON notifications(user_id,read_at,created_at);
CREATE TABLE subscriptions (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), status TEXT NOT NULL CHECK(status IN ('pending','active','past_due','paused','cancelled','expired')), starts_at TEXT, current_period_ends_at TEXT, expires_at TEXT, payment_provider TEXT, external_customer_id TEXT, external_subscription_id TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(payment_provider,external_subscription_id));
CREATE INDEX subscriptions_user_status_idx ON subscriptions(user_id,status);
